query:
query Diablo4TopBannerQuery {
  game: diablo4 {
    settings {
      banners {
        topBanners {
          ...NgfTopBannerFragment
        }
      }
    }
  }
}

fragment NgfTopBannerFragment on NgfTopBanner {
  enabled
  display {
    ...NgfBannerDisplayFragment
  }
  content {
    __typename
    text
    linkText
    linkURL
    openLinkInNewTab
    background {
      simple
      advanced
    }
    withCloseButton
  }
}

fragment NgfBannerDisplayFragment on NgfBannerDisplay {
  slug
  abTestKey
  allowedUserLevels
  platform
  whiteListUserIds
  countries
  minScreenWidth
  countries
  urlMatchPatterns
  distribution
  urlExcludePatterns
}
